\xef\xbb\xbfusing System; using System.Collections.Generic; using System.Diagnostics; using System.IO; using System.Linq; using System.Numerics; using System.Text; using System.Threading.Tasks; namespace GCJ2013QualC { class Program { /// <summary> /// \xe3\x82\xb9\xe3\x83\xac\xe3\x83\x83\xe3\x83\x89\xe6\x95\xb0 /// </summary> static int ThreadCount = 1; /// <summary> /// \xe9\x80\xb2\xe6\x8d\x97\xe3\x82\x92\xe8\xa1\xa8\xe7\xa4\xba\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82 /// </summary> static bool Verbose = false; static int ProgressInterval = 1; class Solver { public List<string> SolveAll(int threadId, StreamReader sr) { // ------------ \xe5\x88\x9d\xe6\x9c\x9f\xe5\x8c\x96 ------------ int T = int.Parse(sr.ReadLine()); // ------------ \xe5\x88\x9d\xe6\x9c\x9f\xe5\x8c\x96 ------------ List<string> outputs = new List<string>(); for (int t = 0; t < T; t++) { // ------------ \xe8\xaa\xad\xe3\x81\xbf\xe8\xbe\xbc\xe3\x81\xbf ------------ BigInteger[] l = sr.ReadLine().Split(\' \').Select(a => BigInteger.Parse(a)).ToArray(); BigInteger A = l[0]; BigInteger B = l[1]; // ------------ \xe8\xaa\xad\xe3\x81\xbf\xe8\xbe\xbc\xe3\x81\xbf ------------ #region if (t % ThreadCount != threadId) { // \xe3\x81\x93\xe3\x81\xae\xe3\x82\xb9\xe3\x83\xac\xe3\x83\x83\xe3\x83\x89\xe3\x81\xae\xe6\x8b\x85\xe5\xbd\x93\xe3\x81\xa7\xe3\x81\xaf\xe3\x81\xaa\xe3\x81\x84\xe3\x81\xae\xe3\x81\xa7\xe8\xa7\xa3\xe3\x81\x8b\xe3\x81\xaa\xe3\x81\x84 continue; } if (Verbose) { if (t % ProgressInterval == 0) { Console.Error.WriteLine(t + " / " + T); } } #endregion // ------------ \xe5\x91\xbc\xe3\x81\xb3\xe5\x87\xba\xe3\x81\x97 ------------ string output = Solve(A, B); // ------------ \xe5\x91\xbc\xe3\x81\xb3\xe5\x87\xba\xe3\x81\x97 ------------ outputs.Add(output); } return outputs; } string Solve(BigInteger A, BigInteger B) { int count = 0; foreach (var p in Palindromes) { if (p * p >= A && p * p <= B) { count++; } else if (p * p > B) { break; } } return count.ToString(); } bool IsPalindromic(BigInteger a) { List<int> vs = new List<int>(); while (a > 0) { vs.Add((int)(a % 10)); a /= 10; } for (int i = 0; i < vs.Count / 2; i++) { if (vs[i] != vs[vs.Count - 1 - i]) { return false; } } return true; } List<BigInteger> Palindromes = new List<BigInteger>(); long DigitMax = 50; public Solver() { BigInteger[] digit1 = new BigInteger[DigitMax + 1]; digit1[0] = 1; for (int i = 0; i < DigitMax; i++) { digit1[i + 1] = digit1[i] * 10; } // 1, 2, 3; Palindromes.Add(1); Palindromes.Add(2); Palindromes.Add(3); for (long d = 1; d <= DigitMax / 2; d++) { BigInteger val; // 1xx1, 1x0x1, 1x1x1, 1x2x1 { val = digit1[0] + digit1[d * 2 - 1]; Palindromes.Add(val); val = digit1[0] + digit1[d * 2]; Palindromes.Add(val); val = digit1[0] + digit1[d] + digit1[d * 2]; Palindromes.Add(val); val = digit1[0] + digit1[d] * 2 + digit1[d * 2]; Palindromes.Add(val); } // 1x1xx1x1, 1x1x0x1x1, 1x1x1x1x1, 1x1x2x1x1 for (long i = 1; i < d; i++) { val = digit1[0] + digit1[i] + digit1[d * 2 - 1 - i] + digit1[d * 2 - 1]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d] + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d] * 2 + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); } // 1x1x1xx1x1x1, 1x1x1x0x1x1x1, 1x1x1x1x1x1x1 for (long i = 1; i < d - 1; i++) { for (long j = i + 1; j < d; j++) { val = digit1[0] + digit1[i] + digit1[d * 2 - 1 - i] + digit1[d * 2 - 1]; val = digit1[0] + digit1[i] + digit1[j] + digit1[d * 2 - 1 - j] + digit1[d * 2 - 1 - i] + digit1[d * 2 - 1]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d * 2 - i] + digit1[d * 2]; val = digit1[0] + digit1[i] + digit1[j] + digit1[d * 2 - j] + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d * 2 - i] + digit1[d * 2]; val = digit1[0] + digit1[i] + digit1[j] + digit1[d] + digit1[d * 2 - j] + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); } } // 1x1x1x1xx1x1x1x1, 1x1x1x1x0x1x1x1x1, 1x1x1x1x1x1x1x1x1 for (long i = 1; i < d - 2; i++) { for (long j = i + 1; j < d - 1; j++) { for (long k = j + 1; k < d; k++) { val = digit1[0] + digit1[i] + digit1[d * 2 - 1 - i] + digit1[d * 2 - 1]; val = digit1[0] + digit1[i] + digit1[j] + digit1[d * 2 - 1 - j] + digit1[d * 2 - 1 - i] + digit1[d * 2 - 1]; val = digit1[0] + digit1[i] + digit1[j] + digit1[k] + digit1[d * 2 - 1 - k] + digit1[d * 2 - 1 - j] + digit1[d * 2 - 1 - i] + digit1[d * 2 - 1]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d * 2 - i] + digit1[d * 2]; val = digit1[0] + digit1[i] + digit1[j] + digit1[k] + digit1[d * 2 - k] + digit1[d * 2 - j] + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); val = digit1[0] + digit1[i] + digit1[d * 2 - i] + digit1[d * 2]; val = digit1[0] + digit1[i] + digit1[j] + digit1[k] + digit1[d] + digit1[d * 2 - k] + digit1[d * 2 - j] + digit1[d * 2 - i] + digit1[d * 2]; Palindromes.Add(val); } } } // 2xx2, 2x0x2, 2x1x2 { val = digit1[0] * 2 + digit1[d * 2 - 1] * 2; Palindromes.Add(val); val = digit1[0] * 2 + digit1[d * 2] * 2; Palindromes.Add(val); val = digit1[0] * 2 + digit1[d] + digit1[d * 2] * 2; Palindromes.Add(val); } } Palindromes.Sort(); #if false foreach (var a in Palindromes) { Debug.Assert(IsPalindromic(a * a)); } #endif } } static void Main(string[] args) { // \xe3\x83\x95\xe3\x82\xa1\xe3\x82\xa4\xe3\x83\xab\xe5\x90\x8d\xe3\x81\x8c\xe6\x8c\x87\xe5\xae\x9a\xe3\x81\x95\xe3\x82\x8c\xe3\x81\xa6\xe3\x81\x84\xe3\x82\x8b\xe5\xa0\xb4\xe5\x90\x88\xe3\x81\xaf\xe3\x80\x81\xe6\x8c\x87\xe5\xae\x9a\xe3\x81\x95\xe3\x82\x8c\xe3\x81\x9f\xe3\x83\x95\xe3\x82\xa1\xe3\x82\xa4\xe3\x83\xab\xe3\x81\xab\xe5\xaf\xbe\xe3\x81\x97\xe3\x81\xa6\xe5\x87\xa6\xe7\x90\x86\xe3\x82\x92\xe8\xa1\x8c\xe3\x81\x86\xe3\x80\x82 // \xe3\x83\x95\xe3\x82\xa1\xe3\x82\xa4\xe3\x83\xab\xe5\x90\x8d\xe3\x81\x8c\xe6\x8c\x87\xe5\xae\x9a\xe3\x81\x95\xe3\x82\x8c\xe3\x81\xa6\xe3\x81\xaa\xe3\x81\x84\xe5\xa0\xb4\xe5\x90\x88\xe3\x81\xaf\xe3\x80\x81\xe3\x82\x