3\x82\x8b\xe3\x80\x82 string outputName = inputName; if (outputName.EndsWith(".in")) { outputName = outputName.Substring(0, outputName.Length - 3); } outputName += ".out"; if (File.Exists(outputName)) { int rev = 1; while (File.Exists(outputName + "." + rev)) { rev++; } File.Move(outputName, outputName + "." + rev); } // \xe5\xae\x9f\xe8\xa1\x8c\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82ThreadCount == 1 \xe3\x81\xaa\xe3\x82\x89\xe3\x80\x81\xe7\x8f\xbe\xe5\x9c\xa8\xe3\x81\xae\xe3\x82\xb9\xe3\x83\xac\xe3\x83\x83\xe3\x83\x89\xe3\x81\xa7\xe3\x80\x81\xe3\x81\x9d\xe3\x82\x8c\xe4\xbb\xa5\xe5\xa4\x96\xe3\x81\xaa\xe3\x82\x89 Parallel \xe3\x81\xa7\xe5\xae\x9f\xe8\xa1\x8c\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82 List<string>[] outputs = new List<string>[ThreadCount]; if (ThreadCount == 1) { for (int i = 0; i < ThreadCount; i++) { Solver solver = new Solver(); StreamReader sr = new StreamReader(inputName); outputs[i] = solver.SolveAll(i, sr); sr.Close(); } } else { Parallel.For(0, ThreadCount, i => { Solver solver = new Solver(); StreamReader sr = new StreamReader(inputName); outputs[i] = solver.SolveAll(i, sr); sr.Close(); }); } // \xe7\xb5\x90\xe6\x9e\x9c\xe3\x82\x92\xe5\x87\xba\xe5\x8a\x9b\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82Case # \xe3\x81\xaf\xe3\x81\x93\xe3\x81\x93\xe3\x81\xa7\xe4\xbb\x98\xe5\x8a\xa0\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82 StreamWriter sw = new StreamWriter(outputName); for (int i = 0; ; i++) { if (outputs[i % ThreadCount].Count > i / ThreadCount) { sw.WriteLine("Case #" + (i + 1) + ": " + outputs[i % ThreadCount][i / ThreadCount]); } else { break; } } sw.Close(); } } } '